import React from 'react';

const topics = [
  "Geography", "Sports", "Religion", "Life", "Nutrition", "Law", "Entertainment", "Crime",
  "Philosophy", "Politics", "Environment", "Sociology", "Science", "Health", "Psychology", "Literature",
  "Technology", "History", "Culture", "Education", "Business", "Economics", "Media", "Art", "Government"
];

export default function PopularTopicsSection() {
  return (
    <section className="py-12 bg-white">
      <h2 className="text-3xl font-bold text-center mb-8">Most Popular Topics</h2>
      <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-4 max-w-6xl mx-auto px-4">
        {topics.map((topic) => (
          <a
            key={topic}
            href={`/topic/${topic.toLowerCase()}`}
            className="bg-gray-50 hover:bg-gray-100 transition rounded-lg p-4 text-center text-black font-medium shadow-sm flex items-center justify-between"
          >
            {topic}
            <span className="ml-2">{'>'}</span>
          </a>
        ))}
      </div>
      {topics.map((topic) => (
        <div class="div-block-57">
          <div class="w-dyn-list">
            <div role="list" class="collection-list-7 w-dyn-items">
              <div role="listitem" class="w-dyn-item">
                <a href="#" class="div-block-56 w-inline-block">
                  <div class="div-block-59">
                    <div class="faq-item-question">
                      <h1 class="sub-h4 faq-item-sh4">{topic}</h1>
                      <img
                        loading="lazy"
                        src="images/CaretRight.svg"
                        alt=""
                        class="learn-more-link-arrow"
                      />
                    </div>
                  </div>
                </a>
              </div>
            </div>
          </div>
        </div>
      ))}
    </section>
  );
}
